SELECT t_inventories.book_id, t_inventories.store_id, m_stores.store_name, m_books.book_title, t_inventories.amount, t_inventories.inventory_status, t_inventories.updated_at FROM ( SELECT DISTINCT t_inventories.store_id FROM m_stores INNER JOIN t_inventories ON m_stores.store_id = t_inventories.store_id LIMIT #{offset}, #{limit} ) store_id_list INNER JOIN t_inventories ON store_id_list.store_id = t_inventories.store_id INNER JOIN m_stores ON m_stores.store_id = t_inventories.store_id INNER JOIN m_books ON t_inventories.book_id = m_books.book_id WHERE t_inventories.deleted_flag = 0
AND ( m_books.book_title LIKE CONCAT('%', #{keyword}, '%') OR m_stores.store_name LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY t_inventories.store_id;

SELECT t_inventories.book_id, t_inventories.store_id, m_books.book_title, t_inventories.amount, t_inventories.inventory_status, t_inventories.updated_at FROM t_inventories INNER JOIN m_books ON t_inventories.book_id = m_books.book_id WHERE t_inventories.deleted_flag = 0
AND m_books.book_title LIKE CONCAT('%', #{keyword}, '%')
AND t_inventories.store_id = #{storeId} ORDER BY t_inventories.store_id LIMIT #{offset}, #{limit};

SELECT count(*) FROM t_inventories INNER JOIN m_books ON t_inventories.book_id = m_books.book_id WHERE t_inventories.deleted_flag = 0
AND m_books.book_title LIKE CONCAT('%', #{keyword}, '%')
AND t_inventories.store_id = #{storeId};
